import{_ as a,o as e,c as s,a5 as l}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"HotSpot 对象布局","description":"一个 Java 对象由对象头、实例字段和对齐填充组成。本文以 64 位 OpenJDK 21.0.12.1 HotSpot 为基线，解释如何计算对象大小、字段为什么不会按声明顺序排列，以及 Mark Word 如何复用同一批位来保存哈希、分代年龄和锁状态。","frontmatter":{},"headers":[],"relativePath":"java/02-jvm-runtime/chapter-03-object-layout.md","filePath":"java/02-jvm-runtime/chapter-03-object-layout.md"}'),i={name:"java/02-jvm-runtime/chapter-03-object-layout.md"};function d(n,t,c,r,o,p){return e(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="hotspot-对象布局" tabindex="-1" data-src-line="1" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">HotSpot 对象布局 <a class="header-anchor" href="#hotspot-对象布局" aria-label="Permalink to &quot;HotSpot 对象布局&quot;">​</a></h1><p data-src-line="3" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">一个 Java 对象由对象头、实例字段和对齐填充组成。本文以 <strong>64 位 OpenJDK 21.0.12.1 HotSpot</strong> 为基线，解释如何计算对象大小、字段为什么不会按声明顺序排列，以及 Mark Word 如何复用同一批位来保存哈希、分代年龄和锁状态。</p><p data-src-line="5" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">以下计算固定使用 <code>-XX:+UseCompressedClassPointers</code>、<code>-XX:+UseCompressedOops</code> 和 <code>-XX:ObjectAlignmentInBytes=8</code>。不同 JVM、CPU 架构或启动参数会得到不同结果，实际值以目标 JVM 的输出为准。</p><h2 id="object-creation" tabindex="-1" data-src-line="7" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">1. new 一个对象发生了什么 <a class="header-anchor" href="#object-creation" aria-label="Permalink to &quot;1. new 一个对象发生了什么 {#object-creation}&quot;">​</a></h2><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">User user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p data-src-line="13" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">HotSpot 执行 <code>new</code> 时主要完成五步：</p><ol data-src-line="15" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><li data-src-line="15" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">检查 <code>User</code> 是否已经加载，必要时先完成类加载。</li><li data-src-line="16" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">计算实例大小，在堆中分配内存。TLAB 内通常只移动分配指针；TLAB 耗尽后才进入共享区竞争。</li><li data-src-line="17" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">将实例字段设置为零值：<code>int</code> 为 0、<code>boolean</code> 为 false、引用为 null。</li><li data-src-line="18" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">写入对象头，包括 Mark Word 和 Klass Pointer。</li><li data-src-line="19" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">执行构造方法 <code>&lt;init&gt;</code>，把字段初始化为程序指定的值。</li></ol><p data-src-line="21" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">第 3 步保证字段在构造方法执行前已有确定值，避免读取到未初始化的内存；第 5 步才执行开发者编写的初始化逻辑。TLAB 和 Eden 分配机制见<a href="./chapter-02-runtime-data-areas.html">运行时数据区与内存结构</a>。</p><h2 id="object-size" tabindex="-1" data-src-line="23" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">2. new Object() 为什么是 16 字节 <a class="header-anchor" href="#object-size" aria-label="Permalink to &quot;2. new Object() 为什么是 16 字节 {#object-size}&quot;">​</a></h2><p data-src-line="25" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">在本文的基线配置下，<code>new Object()</code> 没有实例字段，大小由对象头和最终填充决定：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Mark Word             8 字节</span></span>
<span class="line"><span>压缩后的 Klass Pointer 4 字节</span></span>
<span class="line"><span>实例字段              0 字节</span></span>
<span class="line"><span>尾部填充              4 字节</span></span>
<span class="line"><span>--------------------------------</span></span>
<span class="line"><span>对象总大小            16 字节</span></span></code></pre></div><p data-src-line="36" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">计算可以概括为：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对象大小 = align_up(字段布局结束位置, ObjectAlignmentInBytes)</span></span></code></pre></div><p data-src-line="42" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">字段布局决定字段的起始偏移和结束位置，<code>ObjectAlignmentInBytes</code> 再把对象总大小补齐到 8 的整数倍。</p><p data-src-line="44" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">关闭压缩类指针后，Klass Pointer 变为 8 字节，<code>new Object()</code> 仍是 16 字节。这说明压缩指针改变的是头部结构，不一定改变每一种对象的最终大小；真正是否减少内存，要看字段和填充是否一起减少。</p><h2 id="_3-普通对象如何排布" tabindex="-1" data-src-line="46" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">3. 普通对象如何排布 <a class="header-anchor" href="#_3-普通对象如何排布" aria-label="Permalink to &quot;3. 普通对象如何排布&quot;">​</a></h2><p data-src-line="48" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">64 位 HotSpot 中，普通实例的基本结构如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>字节偏移</span></span>
<span class="line"><span>0            8                 12                 16</span></span>
<span class="line"><span>+------------+-----------------+------------------+</span></span>
<span class="line"><span>| Mark Word  | Klass Pointer   | 实例字段或填充     |</span></span>
<span class="line"><span>|  8 字节     | 4 字节（压缩）    | 从偏移 12 开始    |</span></span>
<span class="line"><span>+------------+-----------------+------------------+</span></span>
<span class="line"><span>                                   ↑</span></span>
<span class="line"><span>                     字段自身仍要满足类型对齐</span></span></code></pre></div><h3 id="_3-1-对象头保存什么" tabindex="-1" data-src-line="61" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">3.1 对象头保存什么 <a class="header-anchor" href="#_3-1-对象头保存什么" aria-label="Permalink to &quot;3.1 对象头保存什么&quot;">​</a></h3><p data-src-line="63" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">对象头包含两部分：</p><ul data-src-line="65" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><li data-src-line="65" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><strong>Mark Word</strong>：64 位 HotSpot 固定占 8 字节，保存 identity hash、分代年龄和锁状态等可复用信息。</li><li data-src-line="66" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><strong>Klass Pointer</strong>：指向类元数据，让 HotSpot 判断对象的实际类型。启用压缩类指针时占 4 字节，否则占 8 字节。</li></ul><p data-src-line="68" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">类的 <code>static</code> 字段不属于对象实例，因此不会出现在这里。实例对象只保存当前类和父类的非静态字段。</p><h3 id="_3-2-压缩类指针与压缩引用不是一回事" tabindex="-1" data-src-line="70" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">3.2 压缩类指针与压缩引用不是一回事 <a class="header-anchor" href="#_3-2-压缩类指针与压缩引用不是一回事" aria-label="Permalink to &quot;3.2 压缩类指针与压缩引用不是一回事&quot;">​</a></h3><p data-src-line="72" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">两个开关压缩的是不同数据：</p><table tabindex="0"><thead data-src-line="74" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="74" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><th style="text-align:left;">开关</th><th style="text-align:left;">压缩对象</th><th style="text-align:left;">对布局的影响</th></tr></thead><tbody data-src-line="76" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="76" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>-XX:+UseCompressedClassPointers</code></td><td style="text-align:left;">对象头中的 <code>Klass*</code></td><td style="text-align:left;">Klass Pointer 从 8 字节变为 4 字节</td></tr><tr data-src-line="77" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>-XX:+UseCompressedOops</code></td><td style="text-align:left;">引用字段和引用数组元素</td><td style="text-align:left;"><code>Object</code> 引用从 8 字节变为 4 字节</td></tr></tbody></table><p data-src-line="79" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">64 位 HotSpot 默认启用压缩类指针。压缩引用会根据堆地址空间等条件自动选择，因此不能只看参数名称就推断最终状态。使用 <code>java -XX:+PrintFlagsFinal -version</code> 查看目标 JVM 的实际值。</p><p data-src-line="81" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">压缩类指针留下的 4 字节并不总是尾部填充：</p><ul data-src-line="83" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><li data-src-line="83" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">普通实例可以把一个 <code>int</code> 或压缩引用放入偏移 12 的位置。</li><li data-src-line="84" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">数组可以用这 4 字节保存 <code>length</code>，因此数组元素从偏移 16 开始。</li></ul><h3 id="_3-3-实例字段按对齐和空洞排列" tabindex="-1" data-src-line="86" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">3.3 实例字段按对齐和空洞排列 <a class="header-anchor" href="#_3-3-实例字段按对齐和空洞排列" aria-label="Permalink to &quot;3.3 实例字段按对齐和空洞排列&quot;">​</a></h3><p data-src-line="88" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">字段类型决定自身占用空间和对齐要求：</p><table tabindex="0"><thead data-src-line="90" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="90" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><th style="text-align:left;">字段类型</th><th style="text-align:left;">大小</th><th style="text-align:left;">对齐要求</th></tr></thead><tbody data-src-line="92" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="92" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>boolean</code>、<code>byte</code></td><td style="text-align:left;">1 字节</td><td style="text-align:left;">1 字节</td></tr><tr data-src-line="93" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>char</code>、<code>short</code></td><td style="text-align:left;">2 字节</td><td style="text-align:left;">2 字节</td></tr><tr data-src-line="94" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>int</code>、<code>float</code>、压缩引用</td><td style="text-align:left;">4 字节</td><td style="text-align:left;">4 字节</td></tr><tr data-src-line="95" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>long</code>、<code>double</code>、未压缩引用</td><td style="text-align:left;">8 字节</td><td style="text-align:left;">8 字节</td></tr></tbody></table><p data-src-line="97" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">HotSpot 会先排列基本类型字段，再排列引用字段，并尝试复用继承布局中的空洞。因此，<strong>字段声明顺序不是内存偏移顺序，父类字段也不保证全部位于子类字段之前</strong>。<code>@Contended</code> 等注解还会主动插入填充。</p><p data-src-line="99" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">以基线配置为例：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Empty</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OneInt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value; }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OneLong</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">long</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> value; }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TwoInts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> first; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> second; }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> OneRef</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Object value; }</span></span></code></pre></div><table tabindex="0"><thead data-src-line="109" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="109" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><th style="text-align:left;">类</th><th style="text-align:left;">布局计算</th><th style="text-align:right;">大小</th></tr></thead><tbody data-src-line="111" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="111" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>Empty</code></td><td style="text-align:left;">12 字节头部 + 4 字节尾部填充</td><td style="text-align:right;">16 字节</td></tr><tr data-src-line="112" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>OneInt</code></td><td style="text-align:left;">12 字节头部 + 4 字节 <code>int</code></td><td style="text-align:right;">16 字节</td></tr><tr data-src-line="113" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>OneLong</code></td><td style="text-align:left;">12 字节头部 + 4 字节对齐空洞 + 8 字节 <code>long</code></td><td style="text-align:right;">24 字节</td></tr><tr data-src-line="114" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>TwoInts</code></td><td style="text-align:left;">12 字节头部 + 2 × 4 字节 <code>int</code> + 4 字节尾部填充</td><td style="text-align:right;">24 字节</td></tr><tr data-src-line="115" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>OneRef</code></td><td style="text-align:left;">12 字节头部 + 4 字节压缩引用</td><td style="text-align:right;">16 字节</td></tr></tbody></table><p data-src-line="117" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">如果关闭压缩引用，<code>OneRef</code> 的引用字段占 8 字节，大小变为 24 字节。具体偏移属于 HotSpot 实现细节，不能作为跨版本 API；需要核对偏移时，应在目标 JVM 上测量。</p><h3 id="_3-4-对齐填充解决什么问题" tabindex="-1" data-src-line="119" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">3.4 对齐填充解决什么问题 <a class="header-anchor" href="#_3-4-对齐填充解决什么问题" aria-label="Permalink to &quot;3.4 对齐填充解决什么问题&quot;">​</a></h3><p data-src-line="121" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">HotSpot 默认要求对象起始地址和总大小按 8 字节对齐，原因是堆分配器、GC 和访问宽度都依赖稳定的字长边界。填充可能出现在字段之间，也可能位于对象末尾。</p><p data-src-line="123" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">因此，两个字段的声明大小之和通常不等于实例数据区大小。例如，<code>OneLong</code> 的头部结束于偏移 12，而 <code>long</code> 必须从 8 的倍数开始，所以偏移 12 到 16 之间必须填充。</p><h2 id="_4-数组对象如何排布" tabindex="-1" data-src-line="125" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">4. 数组对象如何排布 <a class="header-anchor" href="#_4-数组对象如何排布" aria-label="Permalink to &quot;4. 数组对象如何排布&quot;">​</a></h2><p data-src-line="127" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">数组对象在普通对象头之后还要保存 <code>length</code>。在本文的压缩类指针配置下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0            8          12       16</span></span>
<span class="line"><span>+------------+----------+--------+----------------------+</span></span>
<span class="line"><span>| Mark Word  | Klass    | length | 元素 0, 元素 1, ...   |</span></span>
<span class="line"><span>|  8 字节     | 4 字节   | 4 字节  | 从偏移 16 开始        |</span></span>
<span class="line"><span>+------------+----------+--------+----------------------+</span></span></code></pre></div><p data-src-line="137" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">数组总大小按下式计算：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数组大小 = align_up(16 + 数组长度 × 元素大小, ObjectAlignmentInBytes)</span></span></code></pre></div><p data-src-line="143" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">基线配置下的例子：</p><table tabindex="0"><thead data-src-line="145" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="145" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><th style="text-align:left;">表达式</th><th style="text-align:left;">计算</th><th style="text-align:right;">大小</th></tr></thead><tbody data-src-line="147" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="147" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>new byte[1]</code></td><td style="text-align:left;"><code>align_up(16 + 1, 8)</code></td><td style="text-align:right;">24 字节</td></tr><tr data-src-line="148" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>new int[3]</code></td><td style="text-align:left;"><code>align_up(16 + 12, 8)</code></td><td style="text-align:right;">32 字节</td></tr><tr data-src-line="149" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>new long[3]</code></td><td style="text-align:left;"><code>align_up(16 + 24, 8)</code></td><td style="text-align:right;">40 字节</td></tr><tr data-src-line="150" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>new Object[3]</code></td><td style="text-align:left;"><code>align_up(16 + 3 × 4, 8)</code></td><td style="text-align:right;">32 字节</td></tr></tbody></table><p data-src-line="152" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">关闭压缩引用时，<code>Object[]</code> 的每个元素由 4 字节变为 8 字节，<code>new Object[3]</code> 变为 40 字节；基本类型数组不变。关闭压缩类指针会改变数组头，所有数组都需要重新计算。</p><h2 id="mark-word-states" tabindex="-1" data-src-line="154" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">5. Mark Word 如何编码锁状态 <a class="header-anchor" href="#mark-word-states" aria-label="Permalink to &quot;5. Mark Word 如何编码锁状态 {#mark-word-states}&quot;">​</a></h2><p data-src-line="156" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">Mark Word 不是一块固定字段，而是一组按状态复用的位。OpenJDK 21 的 64 位普通对象格式为：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>位范围       63..39       38..8       7       6..3       2       1..0</span></span>
<span class="line"><span>字段         unused:25    hash:31     gap     age:4      gap     lock:2</span></span></code></pre></div><ul data-src-line="163" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><li data-src-line="163" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><code>hash</code> 保存最多 31 位的 identity hash。尚未调用 <code>hashCode()</code> 时，对应位可以为 0。</li><li data-src-line="164" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><code>age</code> 占 4 位，记录对象经历的年龄归档次数。<code>MaxTenuringThreshold=15</code> 是上限，不保证每次 GC 都晋升到阈值；GC 还可能根据 Survivor 容量选择更低的有效阈值。</li><li data-src-line="165" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">最低两位 <code>lock</code> 标识对象状态：</li></ul><table tabindex="0"><thead data-src-line="167" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="167" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><th style="text-align:left;"><code>lock</code></th><th style="text-align:left;">状态</th><th style="text-align:left;">Mark Word 中的主要内容</th></tr></thead><tbody data-src-line="169" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><tr data-src-line="169" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>01</code></td><td style="text-align:left;">普通、未锁定</td><td style="text-align:left;">identity hash、分代年龄和保留位</td></tr><tr data-src-line="170" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>00</code></td><td style="text-align:left;">已锁定</td><td style="text-align:left;">保存锁记录、displaced header 或带锁定标记的 header，具体取决于锁定模式</td></tr><tr data-src-line="171" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>10</code></td><td style="text-align:left;">Monitor 已膨胀</td><td style="text-align:left;">指向 <code>ObjectMonitor</code></td></tr><tr data-src-line="172" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><td style="text-align:left;"><code>11</code></td><td style="text-align:left;">GC 标记</td><td style="text-align:left;">GC 运行期间使用的标记信息</td></tr></tbody></table><p data-src-line="174" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">对象被锁定时，哈希、年龄和锁信息不能同时占据原来的全部位。HotSpot 会在执行 <code>hashCode()</code> 或恢复对象头时保留或重建这些信息，而不是简单丢弃。</p><p data-src-line="176" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">偏向锁属于历史实现，不进入本文的 OpenJDK 21 基线：</p><ul data-src-line="178" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><li data-src-line="178" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">OpenJDK 8u504 的 64 位 Mark Word 包含 <code>biased_lock</code> 位，偏向状态下还保存 ThreadID 和 Epoch。</li><li data-src-line="179" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">OpenJDK 17 仍接受 <code>-XX:+UseBiasedLocking</code>，但会提示该选项自 15 起已弃用。</li><li data-src-line="180" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">OpenJDK 21.0.12.1 的 HotSpot 源码不再包含偏向锁格式。</li></ul><p data-src-line="182" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">锁记录、Monitor 膨胀和锁升级的运行过程见 <a href="./../03-java-concurrency/chapter-06-synchronized.html#synchronized-lock-optimization"><code>synchronized</code> 锁优化</a>。</p><h2 id="verify-layout" tabindex="-1" data-src-line="184" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">6. 如何核对目标 JVM 的布局 <a class="header-anchor" href="#verify-layout" aria-label="Permalink to &quot;6. 如何核对目标 JVM 的布局 {#verify-layout}&quot;">​</a></h2><p data-src-line="186" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">先核对决定布局的参数：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -XX:+PrintFlagsFinal</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -version</span></span></code></pre></div><p data-src-line="192" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">重点检查以下输出是否与预期一致：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bool  UseCompressedClassPointers  = true</span></span>
<span class="line"><span>bool  UseCompressedOops           = true</span></span>
<span class="line"><span>int   ObjectAlignmentInBytes      = 8</span></span></code></pre></div><p data-src-line="200" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">需要查看具体偏移和字段间距时，使用 <a href="https://github.com/openjdk/jol" target="_blank" rel="noreferrer">OpenJDK JOL</a>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/jol-cli-full.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> internals</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> java.lang.Object</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/jol-cli-full.jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> internals</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.example.User</span></span></code></pre></div><p data-src-line="207" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">JOL 必须运行在与目标布局一致的 JVM 配置上。它输出的是当前进程的测量结果，不是跨版本保证。</p><p data-src-line="209" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><code>-XX:+PrintFieldLayout</code> 只存在于 HotSpot 的 debug 或 notproduct 构建中；普通发行版会提示该选项不可用，不能把它当作通用布局检查命令。</p><blockquote data-src-line="211" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><p data-src-line="211" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">版本依据：布局计算核对 OpenJDK <code>jdk-21.0.12.1-ga</code> 中的 <code>markWord.hpp</code>、<code>instanceOop.hpp</code>、<code>arrayOop.hpp</code>、<code>fieldLayoutBuilder.cpp</code> 和 <code>globals.hpp</code>；偏向锁历史格式对照 <code>jdk8u504-ga</code> 中的 <code>markOop.hpp</code>，核对日期为 2026-10-09。</p></blockquote><blockquote data-src-line="213" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md"><p data-src-line="213" data-src-file="java/02-jvm-runtime/chapter-03-object-layout.md">本章解释对象在堆中的实际排布。对象分配区域和 TLAB 见<a href="./chapter-02-runtime-data-areas.html">运行时数据区与内存结构</a>，Mark Word 如何服务 GC 见<a href="./chapter-04-gc.html">垃圾回收</a>，锁状态的运行方式见 <a href="./../03-java-concurrency/chapter-06-synchronized.html#synchronized-lock-optimization"><code>synchronized</code> 锁优化</a>。</p></blockquote>`,67)])])}const j=a(i,[["render",d]]);export{m as __pageData,j as default};
